create table account_table (region_code varchar(4), account_id bigint not null auto_increment, created datetime(6) not null, postal_code varchar(8) not null, phone_number varchar(17), address_one TEXT not null, address_two TEXT, email TEXT not null, first_name TEXT not null, last_name TEXT not null, mobile_pin TEXT, password TEXT not null, two_factor_secret TEXT, username TEXT not null, primary key (account_id)) engine=InnoDB;
create table admin_notifications_table (is_acknowledged bit not null, priority TINYINT not null, account_id bigint not null, admin_notification_id bigint not null auto_increment, created datetime(6) not null, description TEXT not null, title TEXT not null, primary key (admin_notification_id)) engine=InnoDB;
create table clock_in_event_table (account_id bigint not null, clock_in_event_id bigint not null auto_increment, created datetime(6) not null, primary key (clock_in_event_id)) engine=InnoDB;
create table clock_in_table (clock_in time(0) not null, clock_out time(0), account_id bigint not null, created datetime(6) not null, clock_id uuid not null, primary key (clock_id)) engine=InnoDB;
create table document_table (created datetime(6) not null, document_id bigint not null auto_increment, file_id uuid, title TEXT not null, primary key (document_id)) engine=InnoDB;
create table files_table (account_id bigint, created datetime(6) not null, created_by bigint, extension varchar(8) not null, file_id uuid not null, name TEXT not null, primary key (file_id)) engine=InnoDB;
create table hazard_files_table (created datetime(6) not null, hazard_id bigint not null, file_id uuid not null, primary key (file_id)) engine=InnoDB;
create table hazard_table (is_draft BOOLEAN DEFAULT TRUE not null, priority TINYINT, account_id bigint not null, action_complete datetime(6), created datetime(6) not null, hazard_id bigint not null auto_increment, question_six datetime(6) not null, question_five TEXT not null, question_four TEXT not null, question_one TEXT not null, question_three TEXT not null, question_two TEXT not null, title TEXT not null, primary key (hazard_id)) engine=InnoDB;
create table leave_table (is_approved bit not null, leave_type_id TINYINT not null, account_id bigint not null, created datetime(6) not null, end_date datetime(6) not null, leave_id bigint not null auto_increment, start_date datetime(6) not null, notes TEXT, response TEXT, primary key (leave_id)) engine=InnoDB;
create table leave_type_table (leave_type_id TINYINT not null auto_increment, colour_bg varchar(6) not null, colour_icon varchar(6) not null, icon_type TEXT not null, name TEXT not null, primary key (leave_type_id)) engine=InnoDB;
create table payslips_table (is_p_sixty bit not null, month TINYINT, year SMALLINT not null, file_id uuid not null, primary key (file_id)) engine=InnoDB;
create table permissions_table (is_admin bit not null, is_manager bit not null, account_id bigint not null, assigned_by bigint, created datetime(6) not null, primary key (account_id)) engine=InnoDB;
create table qualifications_table (account_id bigint not null, created datetime(6) not null, qualification_id bigint not null auto_increment, file_id uuid, details varchar(255), title varchar(255), primary key (qualification_id)) engine=InnoDB;
create table risk_assessment_hazard_table (created datetime(6) not null, hazard_id bigint not null, risk_assessment_id bigint not null, primary key (hazard_id, risk_assessment_id)) engine=InnoDB;
create table risk_assessment_table (created datetime(6) not null, risk_assessment_id bigint not null auto_increment, file_id uuid, title TEXT not null, primary key (risk_assessment_id)) engine=InnoDB;
create table session_table (is_mobile bit not null, is_two_factor bit not null, account_id bigint, created datetime(6) not null, expires datetime(6) not null, session_id uuid not null, refresh_token TEXT not null, primary key (session_id)) engine=InnoDB;
create table settings_table (dictation bit not null, dyslexic_font bit not null, large_text bit not null, silent_end time(0), silent_start time(0), text_to_speech bit not null, account_id bigint not null, primary key (account_id)) engine=InnoDB;
create table signature_table (account_id bigint not null, created datetime(6) not null, document_id bigint, hazard_id bigint, risk_assessment_id bigint, signature_id uuid not null, primary key (signature_id)) engine=InnoDB;
create table themes_table (accent varchar(6) not null, background varchar(6) not null, midground varchar(6) not null, text varchar(6) not null, account_id bigint not null, primary key (account_id)) engine=InnoDB;
